哈希表是实现高效查找的重要数据结构：

class HashTable:
    def __init__(self, size=50):
        self.size = size
        self.table = [[] for _ in range(size)]

    def _hash(self, key):
        return hash(key) % self.size

    def set(self, key, value):
        hash_key = self._hash(key)
        bucket = self.table[hash_key]

        for i, (k, v) in enumerate(bucket):
            if k == key:
                bucket[i] = (key, value)
                return

        bucket.append((key, value))

    def get(self, key):
        hash_key = self._hash(key)
        bucket = self.table[hash_key]

        for k, v in bucket:
            if k == key:
                return v

        raise KeyError(key)

    def delete(self, key):
        hash_key = self._hash(key)
        bucket = self.table[hash_key]

        for i, (k, v) in enumerate(bucket):
            if k == key:
                del bucket[i]
                return

        raise KeyError(key)

    def __str__(self):
        return str(self.table)

# 使用示例
ht = HashTable()
ht.set("name", "Alice")
ht.set("age", 25)
ht.set("city", "New York")
print(ht.get("name"))  # 输出: Alice
ht.set("name", "Bob")
print(ht.get("name"))  # 输出: Bob
ht.delete("city")
try:
    print(ht.get("city"))
except KeyError as e:
    print(f"Key not found: {e}")
